def voice_watch(mem):
    """W7 round 4: "Hey Scout" (bestly-voice, /opt/bestly/voice). Self-heals, then tells Scout:
    service down or frozen -> restart (max 3 an hour); mic unplugged; speech-to-text / Scout / speaker failures;
    too many false wakes (the service already raises its own threshold a notch; Scout hears if it keeps happening)."""
    vs = load("/opt/bestly/voice/status.json", {})
    st = load(os.path.join(ROOT, "state.json"), {})
    on = (st.get("voice") or {}).get("on") is not False
    try:
        active = subprocess.run(["systemctl", "is-active", "bestly-voice"], capture_output=True, text=True, timeout=10).stdout.strip() == "active"
    except Exception:
        active = True
    age = time.time() - (vs.get("at") or 0)
    rs = [t for t in mem.get("voice_restarts", []) if time.time() - t < 3600]
    if not active or age > 90:
        if len(rs) < 3:
            subprocess.run(["sudo", "-n", "systemctl", "restart", "bestly-voice"], capture_output=True, timeout=30)
            rs.append(time.time())
            log(f"voice: restarted bestly-voice (active={active}, status {int(age)} s old)")
        if len(rs) >= 2:
            report(mem, "wall.voice", "problem", "warning", "Hey Scout keeps stopping",
                   f"The voice service on the Pi stopped or froze {len(rs)} times in the last hour; the Pi restarted it each time "
                   f"(max 3 an hour). Log: /opt/bestly/voice/voice.log.")
    elif age < 60:
        report(mem, "wall.voice", "resolved", "info", "Hey Scout is listening", "The voice service on the Pi is running again.")
    mem["voice_restarts"] = rs
    if not vs:
        return
    # mic unplugged / not answering for 2+ minutes
    if vs.get("mic_ok") is False:
        mem.setdefault("voice_mic_bad", time.time())
        if time.time() - mem["voice_mic_bad"] > 120:
            report(mem, "wall.voice_mic", "problem", "warning", "Hey Scout can't hear: the mic is missing",
                   f"The NZXT USB mic on the Pi isn't working ({vs.get('mic_err') or 'no audio'}). Check it's plugged into the Pi; "
                   "the voice service picks it up again by itself within a few seconds.")
    else:
        mem.pop("voice_mic_bad", None)
        report(mem, "wall.voice_mic", "resolved", "info", "Hey Scout's mic is back", "The NZXT mic is connected and listening.")
    errs = vs.get("errors") or {}
    n = lambda k: len([e for e in (errs.get(k) or []) if time.time() - e[0] < 3600])
    if n("stt") + n("llm") >= 3:
        last = ((errs.get("llm") or errs.get("stt") or [[0, ""]])[-1])[1]
        report(mem, "wall.voice_ai", "problem", "warning", "Hey Scout can't understand or answer",
               f"{n('stt')} speech-to-text and {n('llm')} Scout failures in the last hour (last: {last}). It uses the free "
               "Groq/Cloudflare Whisper and the free LLM ladder through the voice-ask function; it retries on its own.")
    elif n("stt") + n("llm") == 0:
        report(mem, "wall.voice_ai", "resolved", "info", "Hey Scout is answering again", "Speech-to-text and Scout replies are working.")
    if n("play") + n("tts") >= 3:
        report(mem, "wall.voice_speaker", "problem", "warning", "Hey Scout can't talk on the Desk HomePod",
               f"{n('play')} HomePod and {n('tts')} voice failures in the last hour; replies fell back to the projector speaker and the wall card.")
    elif n("play") + n("tts") == 0:
        report(mem, "wall.voice_speaker", "resolved", "info", "Hey Scout talks on the HomePod again", "Spoken replies are playing on the Desk HomePod.")
    fw = ((vs.get("hour") or {}).get("false") or 0)
    if on and fw >= 6:
        rt = vs.get("retuned") or {}
        report(mem, "wall.voice_false", "problem", "info", "Hey Scout is waking up by mistake",
               f"{fw} false wakes in the last hour (woke, then heard nothing useful). "
               + (f"It raised its wake threshold from {rt.get('from')} to {rt.get('to')} by itself. " if rt else "")
               + "If it keeps happening, set Sensitivity to Low in admin > Wall > Voice.")
    elif fw <= 1:
        report(mem, "wall.voice_false", "resolved", "info", "Hey Scout false wakes are down", "Fewer than 2 false wakes in the last hour.")

